"use client"

import { revalidateLogic } from "@tanstack/react-form"
import { BuildingIcon, UsersIcon } from "lucide-react"
import { useMemo } from "react"

import { FieldGroup } from "@/components/ui/field"
import {
  FormDialog,
  FormDialogBody,
  FormDialogCancel,
  FormDialogDescription,
  FormDialogError,
  FormDialogFooter,
  FormDialogForm,
  FormDialogHeader,
  FormDialogSubmit,
  FormDialogTitle,
} from "@/components/openlmis/form-dialog/form-dialog"
import { useDialogTarget } from "@/components/openlmis/form-dialog/use-dialog-target"
import { useAppForm } from "@/components/openlmis/form-fields/form"
import { FieldSkeleton } from "@/components/openlmis/form-fields/form-fields"

import {
  ASSIGNMENT_LABELS,
  type AssignmentChoice,
  type AssignmentChoices,
  type AssignmentKind,
  assignmentFormSchema,
  EMPTY_ASSIGNMENT_FORM,
  type NewAssignment,
  toNewAssignment,
} from "@/components/openlmis/valid-assignments-page/assignment-form"

type AddAssignmentDialogProps = AssignmentChoices & {
  kind: AssignmentKind
  open: boolean
  onClose: () => void
  /** Offers organizations, places outside the system, as well as facilities. */
  canPickOrganizations?: boolean
  /** Locks the dialog and spins Add while the parent saves. */
  pending?: boolean
  /** Why the last save failed; what was picked stays on screen. */
  error?: string
  /** The parent saves it, then closes the dialog or passes `error`. */
  onSubmit: (assignment: NewAssignment) => void
}

export function AddAssignmentDialog({
  open,
  onClose,
  pending = false,
  ...props
}: AddAssignmentDialogProps) {
  const { shown, dialogProps } = useDialogTarget(open || undefined, onClose)

  return (
    <FormDialog {...dialogProps(pending)}>
      {shown && <AddAssignmentForm pending={pending} {...props} />}
    </FormDialog>
  )
}

const toItems = (choices: readonly AssignmentChoice[]) =>
  choices.map((choice) => ({
    value: choice.id,
    label: choice.name,
    description: choice.code,
  }))

function AddAssignmentForm({
  kind,
  canPickOrganizations = false,
  pending,
  error,
  onSubmit,
  programs,
  facilityTypes,
  facilities,
  organizations,
  geoLevels,
}: Omit<AddAssignmentDialogProps, "open" | "onClose"> & { pending: boolean }) {
  const labels = ASSIGNMENT_LABELS[kind]
  const programItems = useMemo(() => programs && toItems(programs), [programs])
  const typeItems = useMemo(
    () => facilityTypes && toItems(facilityTypes),
    [facilityTypes]
  )
  const facilityItems = useMemo(
    () => facilities && toItems(facilities),
    [facilities]
  )
  const organizationItems = useMemo(
    () => organizations && toItems(organizations),
    [organizations]
  )
  const levelItems = useMemo(
    () =>
      geoLevels?.map((level) => ({
        value: level.id,
        label: level.name,
        description: `Level ${level.levelNumber}`,
      })),
    [geoLevels]
  )

  const form = useAppForm({
    defaultValues: EMPTY_ASSIGNMENT_FORM,
    validationLogic: revalidateLogic({
      mode: "submit",
      modeAfterSubmission: "change",
    }),
    validators: { onDynamic: assignmentFormSchema },
    onSubmit: ({ value }) => onSubmit(toNewAssignment(value)),
  })

  const loading = !programItems || !typeItems

  return (
    <FormDialogForm onSubmit={() => void form.handleSubmit()}>
      <FormDialogHeader>
        <FormDialogTitle>Add {labels.one}</FormDialogTitle>
        <FormDialogDescription>
          Let facilities of a type {labels.flow} a facility or an organization
          in a program.
        </FormDialogDescription>
      </FormDialogHeader>
      <FormDialogBody>
        <FieldGroup>
          {error && <FormDialogError description={error} title="Not Added" />}
          {programItems ? (
            <form.AppField name="programId">
              {(field) => (
                <field.SelectField
                  disabled={pending}
                  items={programItems}
                  label="Program"
                  required
                />
              )}
            </form.AppField>
          ) : (
            <FieldSkeleton label="Program" required />
          )}
          {typeItems ? (
            <form.AppField name="facilityTypeId">
              {(field) => (
                <field.SelectField
                  disabled={pending}
                  items={typeItems}
                  label="Facility Type"
                  required
                />
              )}
            </form.AppField>
          ) : (
            <FieldSkeleton label="Facility Type" required />
          )}
          {canPickOrganizations && (
            <form.AppField name="nodeType">
              {(field) => (
                <field.RadioGroupField
                  columns="row"
                  disabled={pending}
                  label="Place"
                  options={[
                    {
                      value: "facility",
                      label: "Facility",
                      description: "A facility in the system.",
                      media: <BuildingIcon />,
                    },
                    {
                      value: "organization",
                      label: "Organization",
                      description:
                        "A place outside the system, such as an NGO.",
                      media: <UsersIcon />,
                    },
                  ]}
                />
              )}
            </form.AppField>
          )}
          <form.Subscribe selector={(state) => state.values.nodeType}>
            {(nodeType) =>
              nodeType === "organization" ? (
                organizationItems ? (
                  <form.AppField name="organizationId">
                    {(field) => (
                      <field.SelectField
                        disabled={pending}
                        items={organizationItems}
                        label="Organization"
                        required
                      />
                    )}
                  </form.AppField>
                ) : (
                  <FieldSkeleton label="Organization" required />
                )
              ) : facilityItems ? (
                <form.AppField name="facilityId">
                  {(field) => (
                    <field.ComboboxField
                      clearLabel="Clear Facility"
                      disabled={pending}
                      emptyMessage="No Matches"
                      items={facilityItems}
                      label="Facility"
                      required
                    />
                  )}
                </form.AppField>
              ) : (
                <FieldSkeleton label="Facility" required />
              )
            }
          </form.Subscribe>
          {levelItems ? (
            <form.AppField name="geoLevelAffinityId">
              {(field) => (
                <field.ComboboxField
                  clearLabel="Clear Geo Level Affinity"
                  description="Offer it only to facilities in the same zone at this level, such as the same district."
                  disabled={pending}
                  emptyMessage="No Matches"
                  items={levelItems}
                  label="Geo Level Affinity"
                />
              )}
            </form.AppField>
          ) : (
            <FieldSkeleton label="Geo Level Affinity" />
          )}
        </FieldGroup>
      </FormDialogBody>
      <FormDialogFooter>
        <FormDialogCancel disabled={pending} />
        <FormDialogSubmit disabled={loading} pending={pending}>
          Add
        </FormDialogSubmit>
      </FormDialogFooter>
    </FormDialogForm>
  )
}

import { z } from "zod"

/** Valid sources say where a facility type may receive stock from; destinations, where it may issue to. */
export type AssignmentKind = "sources" | "destinations"

export const ASSIGNMENT_LABELS = {
  sources: {
    one: "Valid Source",
    many: "Valid Sources",
    flow: "receive stock from",
  },
  destinations: {
    one: "Valid Destination",
    many: "Valid Destinations",
    flow: "issue stock to",
  },
} as const satisfies Record<
  AssignmentKind,
  { one: string; many: string; flow: string }
>

export type AssignmentChoice = {
  id: string
  name: string
  /** Muted beside the name, e.g. a facility's code. */
  code?: string
}

export type GeoLevelChoice = {
  id: string
  name: string
  levelNumber: number
}

/** The dialog's lists; one left undefined shows a skeleton in its field. */
export type AssignmentChoices = {
  programs: readonly AssignmentChoice[] | undefined
  facilityTypes: readonly AssignmentChoice[] | undefined
  facilities: readonly AssignmentChoice[] | undefined
  organizations: readonly AssignmentChoice[] | undefined
  geoLevels: readonly GeoLevelChoice[] | undefined
}

export type AssignmentNodeType = "facility" | "organization"

/** What the dialog submits: the place is a facility or an organization, never both. */
export type NewAssignment = {
  programId: string
  facilityTypeId: string
  nodeType: AssignmentNodeType
  nodeId: string
  geoLevelAffinityId: string | null
}

export const assignmentFormSchema = z
  .object({
    programId: z.string().min(1, "Pick a program."),
    facilityTypeId: z.string().min(1, "Pick a facility type."),
    nodeType: z.enum(["facility", "organization"]),
    facilityId: z.string().nullable(),
    organizationId: z.string(),
    geoLevelAffinityId: z.string().nullable(),
  })
  .superRefine((values, context) => {
    if (values.nodeType === "facility" && !values.facilityId) {
      context.addIssue({
        code: "custom",
        path: ["facilityId"],
        message: "Pick a facility.",
      })
    }
    if (values.nodeType === "organization" && !values.organizationId) {
      context.addIssue({
        code: "custom",
        path: ["organizationId"],
        message: "Pick an organization.",
      })
    }
  })

export type AssignmentFormValues = z.infer<typeof assignmentFormSchema>

export const EMPTY_ASSIGNMENT_FORM: AssignmentFormValues = {
  programId: "",
  facilityTypeId: "",
  nodeType: "facility",
  facilityId: null,
  organizationId: "",
  geoLevelAffinityId: null,
}

/** Only the place of the choice shown is sent; each side keeps its pick while the other is shown. */
export function toNewAssignment(values: AssignmentFormValues): NewAssignment {
  return {
    programId: values.programId,
    facilityTypeId: values.facilityTypeId,
    nodeType: values.nodeType,
    nodeId:
      values.nodeType === "facility"
        ? (values.facilityId ?? "")
        : values.organizationId,
    geoLevelAffinityId: values.geoLevelAffinityId,
  }
}

"use client"

import { createColumnHelper } from "@tanstack/react-table"
import { EllipsisIcon, Trash2Icon } from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import {
  DataTableColumnHeader,
  type DataTableFeatures,
} from "@/components/blocks/openlmis/data-table/data-table"
import type { ResponsiveColumn } from "@/components/blocks/openlmis/data-table/responsive-columns"
import { selectionColumn } from "@/components/openlmis/table-selection"

import type { ValidAssignment } from "@/components/openlmis/valid-assignments-page/mock-assignments"

export type AssignmentRow = ValidAssignment & {
  name: string
  /** The name with its facility type and program, which tells apart rows that share a place. */
  rowName: string
  program: string
  facilityType: string
  /** Null for an organization, which has no zone. */
  geoZone: string | null
  geoLevel: string | null
}

export const HIDEABLE_COLUMNS = [
  { id: "program", label: "Program", hideBelow: "lg" },
  { id: "facilityType", label: "Facility Type", hideBelow: "lg" },
  { id: "geoZone", label: "Geo Zone", hideBelow: "xl" },
  { id: "geoLevelAffinity", label: "Geo Level Affinity", hideBelow: "3xl" },
] as const satisfies readonly (ResponsiveColumn & { label: string })[]

const columnHelper = createColumnHelper<DataTableFeatures, AssignmentRow>()

const muted = (text: string) => (
  <span className="text-muted-foreground">{text}</span>
)

const wrapped = (text: string) => (
  <span className="block wrap-break-word whitespace-normal" dir="auto">
    {text}
  </span>
)

export function createAssignmentColumns(
  onDelete: (row: AssignmentRow) => void
) {
  return columnHelper.columns([
    selectionColumn<AssignmentRow>((row) => row.rowName),
    columnHelper.accessor("program", {
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Program" />
      ),
      cell: ({ getValue }) => wrapped(getValue()),
    }),
    columnHelper.accessor("facilityType", {
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Facility Type" />
      ),
      cell: ({ getValue }) => wrapped(getValue()),
    }),
    columnHelper.accessor("name", {
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Name" />
      ),
      // Hidden program and type columns fold in under the name, so a narrow table still tells rows apart.
      cell: ({ row, table }) => {
        const folded = (["program", "facilityType"] as const)
          .filter((id) => !table.getColumn(id)?.getIsVisible())
          .map((id) => row.original[id])
        return (
          <span
            className="flex flex-col wrap-break-word whitespace-normal"
            dir="auto"
          >
            <span className="font-medium">{row.original.name}</span>
            {folded.length > 0 && muted(folded.join(" · "))}
          </span>
        )
      },
      meta: { className: "@2xl/table:w-1/4" },
    }),
    columnHelper.accessor("geoZone", {
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Geo Zone" />
      ),
      cell: ({ getValue }) => {
        const zone = getValue()
        return zone === null ? muted("Organization") : wrapped(zone)
      },
    }),
    columnHelper.accessor("geoLevel", {
      id: "geoLevelAffinity",
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Geo Level Affinity" />
      ),
      cell: ({ getValue }) => {
        const level = getValue()
        return level === null ? muted("-") : wrapped(level)
      },
    }),
    columnHelper.display({
      id: "actions",
      header: () => <span className="sr-only">Actions</span>,
      meta: { className: "w-16" },
      cell: ({ row }) => (
        <AssignmentActions
          label={row.original.rowName}
          onDelete={() => onDelete(row.original)}
        />
      ),
    }),
  ])
}

function AssignmentActions({
  label,
  onDelete,
}: {
  label: string
  onDelete: () => void
}) {
  return (
    <div className="flex justify-end">
      <DropdownMenu>
        <DropdownMenuTrigger
          render={
            <Button
              aria-label={`Actions For ${label}`}
              size="icon-sm"
              variant="ghost"
            />
          }
        >
          <EllipsisIcon />
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end" className="w-auto">
          <DropdownMenuItem onClick={onDelete} variant="destructive">
            <Trash2Icon />
            Delete
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  )
}

"use client"

import { useMemo, useRef, useState } from "react"

import {
  ASSIGNMENT_LABELS,
  type AssignmentKind,
  type NewAssignment,
} from "@/components/openlmis/valid-assignments-page/assignment-form"
import type {
  AssignmentTargets,
  DeleteAssignmentsResult,
} from "@/components/openlmis/valid-assignments-page/delete-assignments-dialog"
import type { CalloutTone } from "@/components/openlmis/callout"

import type { AssignmentRow } from "@/components/openlmis/valid-assignments-page/assignment-columns"
import {
  MOCK_FACILITIES,
  MOCK_FACILITY_TYPES,
  MOCK_GEO_LEVELS,
  MOCK_ORGANIZATIONS,
  MOCK_PROGRAMS,
  type ValidAssignment,
} from "@/components/openlmis/valid-assignments-page/mock-assignments"

export type AssignmentFilters = { facilityId: string; programId: string }

export type AssignmentNotice = {
  tone: CalloutTone
  title: string
  description: string
}

const NO_FILTERS: AssignmentFilters = { facilityId: "", programId: "" }
const NOTHING_PICKED: AssignmentTargets = new Map()

const nameIn = (list: readonly { id: string; name: string }[], id: string) =>
  list.find((item) => item.id === id)?.name ?? "Unknown"

function toRow(assignment: ValidAssignment): AssignmentRow {
  const facility =
    assignment.nodeType === "facility"
      ? MOCK_FACILITIES.find((item) => item.id === assignment.nodeId)
      : undefined
  const name = facility?.name ?? nameIn(MOCK_ORGANIZATIONS, assignment.nodeId)
  const program = nameIn(MOCK_PROGRAMS, assignment.programId)
  const facilityType = nameIn(MOCK_FACILITY_TYPES, assignment.facilityTypeId)
  return {
    ...assignment,
    name,
    rowName: `${name} for ${facilityType} in ${program}`,
    program,
    facilityType,
    geoZone: facility ? facility.geoZone : null,
    geoLevel: assignment.geoLevelAffinityId
      ? nameIn(MOCK_GEO_LEVELS, assignment.geoLevelAffinityId)
      : null,
  }
}

/** The server takes the facility and the program only as a pair. */
export const isHalfFiltered = ({ facilityId, programId }: AssignmentFilters) =>
  Boolean(facilityId) !== Boolean(programId)

/** One list of valid sources or destinations, filtered, paged and edited in memory. */
export function useAssignments(
  kind: AssignmentKind,
  assignments: ValidAssignment[],
  onAssignmentsChange: (next: ValidAssignment[]) => void
) {
  const labels = ASSIGNMENT_LABELS[kind]
  const [filters, setFilters] = useState(NO_FILTERS)
  const [pagination, setPagination] = useState({ pageIndex: 0, pageSize: 10 })
  const [picked, setPicked] = useState(NOTHING_PICKED)
  const [notice, setNotice] = useState<AssignmentNotice>()
  const added = useRef(0)

  const rows = useMemo(() => {
    const { facilityId, programId } = filters
    const facility = MOCK_FACILITIES.find((item) => item.id === facilityId)
    return assignments
      .filter(
        (assignment) =>
          !facility ||
          (assignment.programId === programId &&
            assignment.facilityTypeId === facility.typeId)
      )
      .map(toRow)
  }, [assignments, filters])

  // A delete can empty the last page, so it falls back to the page that is left.
  const lastPage = Math.max(0, Math.ceil(rows.length / pagination.pageSize) - 1)
  const pageIndex = Math.min(pagination.pageIndex, lastPage)
  const pageRows = useMemo(
    () =>
      rows.slice(
        pageIndex * pagination.pageSize,
        (pageIndex + 1) * pagination.pageSize
      ),
    [rows, pageIndex, pagination.pageSize]
  )

  // The selection belongs to one filter, so changing it starts over.
  const updateFilters = (patch: Partial<AssignmentFilters>) => {
    setFilters((current) => ({ ...current, ...patch }))
    setPagination((current) => ({ ...current, pageIndex: 0 }))
    setPicked(NOTHING_PICKED)
  }

  const add = (draft: NewAssignment) => {
    const program = nameIn(MOCK_PROGRAMS, draft.programId)
    const type = nameIn(MOCK_FACILITY_TYPES, draft.facilityTypeId)
    const existing = assignments.find(
      (assignment) =>
        assignment.programId === draft.programId &&
        assignment.facilityTypeId === draft.facilityTypeId &&
        assignment.nodeId === draft.nodeId
    )
    if (existing) {
      setNotice({
        tone: "info",
        title: `Already A ${labels.one}`,
        description: `${toRow(existing).name} was already offered to ${type} in ${program}, so nothing was changed.`,
      })
      return
    }
    added.current += 1
    const assignment: ValidAssignment = {
      ...draft,
      id: `${kind}-new-${added.current}`,
    }
    onAssignmentsChange([assignment, ...assignments])
    setNotice({
      tone: "success",
      title: `${labels.one} Added`,
      description: `${toRow(assignment).name} is now offered to ${type} in ${program}.`,
    })
  }

  const remove = (ids: string[]): DeleteAssignmentsResult => {
    const locked = new Set(
      assignments.filter((item) => item.locked).map((item) => item.id)
    )
    const deleted = ids.filter((id) => !locked.has(id))
    const failed = ids.filter((id) => locked.has(id))
    if (deleted.length === 0) return { deleted, failed }

    onAssignmentsChange(
      assignments.filter((item) => !deleted.includes(item.id))
    )
    // The ones that failed stay selected, so the user can try again.
    setPicked(
      (current) => new Map([...current].filter(([id]) => !deleted.includes(id)))
    )
    setNotice(
      failed.length === 0
        ? {
            tone: "success",
            title:
              deleted.length === 1
                ? `${labels.one} Deleted`
                : `${labels.many} Deleted`,
            description:
              deleted.length === 1
                ? "1 was deleted."
                : `${deleted.length} were deleted.`,
          }
        : {
            tone: "warning",
            title: "Some Were Not Deleted",
            description: `${deleted.length} deleted, ${failed.length} could not be. Those are still selected, so you can try again.`,
          }
    )
    return { deleted, failed }
  }

  return {
    filters,
    updateFilters,
    clearFilters: () => updateFilters(NO_FILTERS),
    isHalfFiltered: isHalfFiltered(filters),
    isFiltered: Boolean(filters.facilityId || filters.programId),
    rows,
    pageRows,
    pagination: { pageIndex, pageSize: pagination.pageSize },
    setPagination,
    picked,
    setPicked,
    notice,
    dismissNotice: () => setNotice(undefined),
    add,
    remove,
  }
}

"use client"

import {
  type ColumnVisibilityState,
  functionalUpdate,
  type RowSelectionState,
  useTable,
} from "@tanstack/react-table"
import {
  ArrowDownToLineIcon,
  ArrowUpFromLineIcon,
  MapPinnedIcon,
  PlusIcon,
  SearchXIcon,
  Trash2Icon,
} from "lucide-react"
import { useCallback, useMemo, useRef, useState } from "react"

import { Button } from "@/components/ui/button"
import {
  ASSIGNMENT_LABELS,
  type AssignmentKind,
} from "@/components/openlmis/valid-assignments-page/assignment-form"
import { AddAssignmentDialog } from "@/components/openlmis/valid-assignments-page/add-assignment-dialog"
import {
  DataTable,
  DataTableCard,
  DataTableEmpty,
  DataTablePagination,
  dataTableFeatures,
} from "@/components/blocks/openlmis/data-table/data-table"
import {
  useColumnVisibility,
  useContainerSize,
} from "@/components/blocks/openlmis/data-table/responsive-columns"
import {
  type AssignmentTargets,
  DeleteAssignmentsDialog,
} from "@/components/openlmis/valid-assignments-page/delete-assignments-dialog"
import {
  ListToolbar,
  ListToolbarEnd,
  ListToolbarFilter,
  ListToolbarSearch,
} from "@/components/blocks/openlmis/list-toolbar"
import {
  Workspace,
  WorkspaceContent,
  WorkspaceDescription,
  WorkspaceHeader,
  WorkspaceHeading,
  WorkspaceIcon,
  WorkspaceTitle,
} from "@/components/blocks/openlmis/workspace"
import { Callout } from "@/components/openlmis/callout"
import { ColumnViewOptions } from "@/components/openlmis/column-view-options"
import { ComboboxFilter } from "@/components/openlmis/combobox-filter"
import { SelectFilter } from "@/components/openlmis/select-filter"
import { DataTableSelectionBar } from "@/components/openlmis/table-selection"
import {
  WorkspaceTabs,
  WorkspaceTabsContent,
  WorkspaceTabsList,
  WorkspaceTabsTrigger,
} from "@/components/openlmis/workspace-tabs"

import {
  type AssignmentRow,
  createAssignmentColumns,
  HIDEABLE_COLUMNS,
} from "@/components/openlmis/valid-assignments-page/assignment-columns"
import {
  MOCK_ASSIGNMENTS,
  MOCK_FACILITIES,
  MOCK_FACILITY_TYPES,
  MOCK_GEO_LEVELS,
  MOCK_ORGANIZATIONS,
  MOCK_PROGRAMS,
  type ValidAssignment,
} from "@/components/openlmis/valid-assignments-page/mock-assignments"
import { useAssignments } from "@/components/openlmis/valid-assignments-page/use-assignments"

const DESCRIPTIONS = {
  sources: "Where each type of facility may receive stock from, per program.",
  destinations: "Where each type of facility may issue stock to, per program.",
} as const satisfies Record<AssignmentKind, string>

const FACILITY_OPTIONS = MOCK_FACILITIES.map((facility) => ({
  value: facility.id,
  label: facility.name,
  description: facility.code,
}))

const PROGRAM_OPTIONS = MOCK_PROGRAMS.map((program) => ({
  value: program.id,
  label: program.name,
}))

const getRowId = (row: AssignmentRow) => row.id

/** Valid sources and destinations as tabs of one screen; mount it from any route, or split the tabs into two routes. */
export function ValidAssignmentsPage() {
  const [kind, setKind] = useState<AssignmentKind>("sources")
  const [assignments, setAssignments] = useState(MOCK_ASSIGNMENTS)
  const labels = ASSIGNMENT_LABELS[kind]
  const Icon =
    kind === "destinations" ? ArrowUpFromLineIcon : ArrowDownToLineIcon

  return (
    <Workspace>
      <WorkspaceHeader>
        <WorkspaceHeading>
          <WorkspaceIcon>
            <Icon />
          </WorkspaceIcon>
          <WorkspaceTitle>{labels.many}</WorkspaceTitle>
          <WorkspaceDescription>{DESCRIPTIONS[kind]}</WorkspaceDescription>
        </WorkspaceHeading>
      </WorkspaceHeader>
      <WorkspaceContent>
        <WorkspaceTabs
          onValueChange={(next) => setKind(next as AssignmentKind)}
          value={kind}
        >
          <WorkspaceTabsList label="Assignment Lists" wrap="grid">
            <WorkspaceTabsTrigger value="sources">
              Valid Sources
            </WorkspaceTabsTrigger>
            <WorkspaceTabsTrigger value="destinations">
              Valid Destinations
            </WorkspaceTabsTrigger>
          </WorkspaceTabsList>
          {(["sources", "destinations"] as const).map((tab) => (
            <WorkspaceTabsContent key={tab} value={tab}>
              <AssignmentsList
                assignments={assignments[tab]}
                kind={tab}
                onAssignmentsChange={(next) =>
                  setAssignments((current) => ({ ...current, [tab]: next }))
                }
              />
            </WorkspaceTabsContent>
          ))}
        </WorkspaceTabs>
      </WorkspaceContent>
    </Workspace>
  )
}

type AssignmentsListProps = {
  kind: AssignmentKind
  assignments: ValidAssignment[]
  onAssignmentsChange: (next: ValidAssignment[]) => void
}

function AssignmentsList({
  kind,
  assignments,
  onAssignmentsChange,
}: AssignmentsListProps) {
  const labels = ASSIGNMENT_LABELS[kind]
  const list = useAssignments(kind, assignments, onAssignmentsChange)
  const { picked, setPicked, pageRows } = list
  const [adding, setAdding] = useState(false)
  const [deleting, setDeleting] = useState<AssignmentTargets>()
  const focusAfterDelete = useRef<HTMLElement>(null)
  const [deletedCount, setDeletedCount] = useState(0)
  const [deleteError, setDeleteError] = useState<string>()

  const [measureContent, contentSize] = useContainerSize<HTMLElement>()
  const contentRef = useCallback(
    (node: HTMLElement | null) => {
      focusAfterDelete.current = node
      measureContent(node)
    },
    [measureContent]
  )
  // Kept for the visit only; store it (e.g. in localStorage) to remember it across visits.
  const columnChoices = useState<ColumnVisibilityState>({})
  const columnView = useColumnVisibility(
    HIDEABLE_COLUMNS,
    columnChoices,
    contentSize
  )

  const deleteOne = useCallback((row: AssignmentRow) => {
    setDeletedCount(0)
    setDeleting(new Map([[row.id, row.rowName]]))
  }, [])
  const columns = useMemo(() => createAssignmentColumns(deleteOne), [deleteOne])
  // Memoized: the table compares controlled state by reference.
  const rowSelection = useMemo<RowSelectionState>(
    () => Object.fromEntries([...picked.keys()].map((id) => [id, true])),
    [picked]
  )

  const table = useTable({
    features: dataTableFeatures,
    columns,
    data: pageRows,
    getRowId,
    rowCount: list.rows.length,
    manualPagination: true,
    enableSorting: false,
    state: {
      pagination: list.pagination,
      columnVisibility: columnView.visibility,
      rowSelection,
    },
    onPaginationChange: (updater) =>
      list.setPagination(functionalUpdate(updater, list.pagination)),
    // Rows on other pages stay selected, named by what was on screen when they were picked.
    onRowSelectionChange: (updater) => {
      const next = functionalUpdate(updater, rowSelection)
      const names = new Map(pageRows.map((row) => [row.id, row.rowName]))
      setPicked(
        new Map(
          Object.keys(next)
            .filter((id) => next[id])
            .map((id) => [id, names.get(id) ?? picked.get(id) ?? id])
        )
      )
    },
  })

  const closeDelete = () => {
    setDeleting(undefined)
    setDeleteError(undefined)
  }

  return (
    // Measured, because the room for columns depends on a sidebar as well as the window.
    <section
      aria-label={labels.many}
      className="flex flex-col gap-4 outline-none @4xl/main:gap-6"
      ref={contentRef}
      tabIndex={-1}
    >
      <ListToolbar>
        <ListToolbarSearch>
          <ComboboxFilter
            label="Available To"
            onValueChange={(facilityId) => list.updateFilters({ facilityId })}
            options={FACILITY_OPTIONS}
            value={list.filters.facilityId}
          />
        </ListToolbarSearch>
        <ListToolbarFilter>
          <SelectFilter
            label="Program"
            onValueChange={(programId) => list.updateFilters({ programId })}
            options={PROGRAM_OPTIONS}
            value={list.filters.programId}
          />
        </ListToolbarFilter>
        <ListToolbarEnd>
          <ColumnViewOptions
            columns={[...HIDEABLE_COLUMNS]}
            onReset={columnView.onReset}
            onVisibilityChange={columnView.onVisibilityChange}
            visibility={columnView.visibility}
          />
        </ListToolbarEnd>
        <div className="w-full @2xl/toolbar:w-auto">
          <Button className="w-full" onClick={() => setAdding(true)}>
            <PlusIcon data-icon="inline-start" />
            Add {labels.one}
          </Button>
        </div>
      </ListToolbar>

      {list.notice && (
        <Callout
          action={
            <Button onClick={list.dismissNotice} size="sm" variant="ghost">
              Dismiss
            </Button>
          }
          title={list.notice.title}
          tone={list.notice.tone}
        >
          {list.notice.description}
        </Callout>
      )}

      {list.isHalfFiltered ? (
        <DataTableCard>
          <DataTableEmpty
            action={
              <Button onClick={list.clearFilters} variant="destructive">
                Clear Filters
              </Button>
            }
            description={
              list.filters.facilityId
                ? "Pick a program as well, to see what this facility may use in it."
                : "Pick a facility as well, to see what it may use in this program."
            }
            icon={<SearchXIcon />}
            title="Pick Both Filters"
          />
        </DataTableCard>
      ) : (
        <DataTable
          empty={
            list.isFiltered ? (
              <DataTableEmpty
                action={
                  <Button onClick={list.clearFilters} variant="destructive">
                    Clear Filters
                  </Button>
                }
                description={`This facility has no ${labels.many.toLowerCase()} in this program.`}
                icon={<SearchXIcon />}
                title="Nothing Available"
              />
            ) : (
              <DataTableEmpty
                description={`Add one to let a facility type ${labels.flow} a place.`}
                icon={<MapPinnedIcon />}
                title={`No ${labels.many} Yet`}
              />
            )
          }
          footer={list.rows.length > 0 && <DataTablePagination table={table} />}
          table={table}
        />
      )}

      <DataTableSelectionBar
        count={picked.size}
        onClear={() => setPicked(new Map())}
      >
        <Button
          onClick={() => {
            setDeletedCount(0)
            setDeleting(picked)
          }}
          size="sm"
          variant="destructive"
        >
          <Trash2Icon data-icon="inline-start" />
          Delete Selected
        </Button>
      </DataTableSelectionBar>

      <DeleteAssignmentsDialog
        deletedCount={deletedCount}
        focusAfterDelete={focusAfterDelete}
        error={deleteError}
        kind={kind}
        onClose={closeDelete}
        onConfirm={(ids) => {
          const { deleted } = list.remove(ids)
          if (deleted.length > 0) {
            setDeletedCount(deleted.length)
            return closeDelete()
          }
          setDeleteError(
            "Nothing was deleted. Check your connection and try again."
          )
        }}
        targets={deleting}
      />
      <AddAssignmentDialog
        canPickOrganizations
        facilities={MOCK_FACILITIES}
        facilityTypes={MOCK_FACILITY_TYPES}
        geoLevels={MOCK_GEO_LEVELS}
        kind={kind}
        onClose={() => setAdding(false)}
        onSubmit={(assignment) => {
          list.add(assignment)
          setAdding(false)
        }}
        open={adding}
        organizations={MOCK_ORGANIZATIONS}
        programs={MOCK_PROGRAMS}
      />
    </section>
  )
}

